package whiteboard

import (
	"encoding/json"
	"math"
	"os"
	"reflect"
	"testing"

	"github.com/OUBIGFA/FreeFolio/internal/whiteboard/rough"
)

// Expected paths are executed from the pinned canvas-harness source used by
// dim0, not generated by the Go implementation being tested.
func TestDim0PathsMatchUpstream(t *testing.T) {
	data, err := os.ReadFile("testdata/dim0-paths.json")
	if err != nil {
		t.Fatal(err)
	}
	var cases []struct {
		Shape        string
		W, H, Radius float64
		Path         string
	}
	if err := json.Unmarshal(data, &cases); err != nil {
		t.Fatal(err)
	}
	for _, tc := range cases {
		a, z := rough.ParsePath(dimShapePath(tc.Shape, 0, 0, tc.W, tc.H, tc.Radius)), rough.ParsePath(tc.Path)
		if len(a) != len(z) {
			t.Fatalf("%s: path segment count %d != %d", tc.Shape, len(a), len(z))
		}
		for i := range a {
			// JSON makes the comparison independent of the parser's segment fields.
			x, _ := json.Marshal(a[i])
			y, _ := json.Marshal(z[i])
			var ax, az any
			_ = json.Unmarshal(x, &ax)
			_ = json.Unmarshal(y, &az)
			if !dimNumbersEqual(ax, az) {
				t.Fatalf("%s segment %d: %s != %s", tc.Shape, i, x, y)
			}
		}
	}
}

func dimNumbersEqual(a, b any) bool {
	switch x := a.(type) {
	case float64:
		y, ok := b.(float64)
		return ok && math.Abs(x-y) < 1e-9
	case []any:
		y, ok := b.([]any)
		if !ok || len(x) != len(y) {
			return false
		}
		for i := range x {
			if !dimNumbersEqual(x[i], y[i]) {
				return false
			}
		}
		return true
	case map[string]any:
		y, ok := b.(map[string]any)
		if !ok || len(x) != len(y) {
			return false
		}
		for k, v := range x {
			if !dimNumbersEqual(v, y[k]) {
				return false
			}
		}
		return true
	default:
		return reflect.DeepEqual(a, b)
	}
}

func TestDim0ShapesRoundTripAndExport(t *testing.T) {
	for _, name := range DimShapeNames {
		s := NewScene()
		e := NewDimShape(name, 10, 20, 180, 110)
		s.Elements = append(s.Elements, e)
		raw, err := s.Encode()
		if err != nil {
			t.Fatal(err)
		}
		loaded, err := Decode(raw)
		if err != nil {
			t.Fatal(err)
		}
		if DimShapeOf(loaded.Elements[0]) != name {
			t.Fatalf("lost shape %s", name)
		}
		if len(ElementPrimitives(e)) == 0 {
			t.Fatalf("empty shape %s", name)
		}
		if _, err := ExportSVG(loaded, SVGOptions{EmbedScene: true}); err != nil {
			t.Fatal(err)
		}
		if !HitTest(e, Point{100, 75}, 3) {
			t.Fatalf("unselectable shape %s", name)
		}
	}
}

func TestDim0ArrowheadsMatchUpstream(t *testing.T) {
	data, err := os.ReadFile("testdata/dim0-arrowheads.json")
	if err != nil {
		t.Fatal(err)
	}
	var cases []struct {
		Kind  string
		Width float64
		Ops   []rough.Op
	}
	if err = json.Unmarshal(data, &cases); err != nil {
		t.Fatal(err)
	}
	for _, tc := range cases {
		p := DimArrowhead(tc.Kind, Point{100, 80}, Point{.6, .8}, tc.Width, "#475569", 1)
		if !reflect.DeepEqual(p.Ops, tc.Ops) {
			t.Fatalf("%s/%g: %+v != %+v", tc.Kind, tc.Width, p.Ops, tc.Ops)
		}
	}
}

func TestDim0BrushMatchesUpstream(t *testing.T) {
	data, err := os.ReadFile("testdata/dim0-brush.json")
	if err != nil {
		t.Fatal(err)
	}
	var cases []struct {
		Points []Point
		Width  float64
		Ring   []Point
	}
	if err = json.Unmarshal(data, &cases); err != nil {
		t.Fatal(err)
	}
	for _, tc := range cases {
		got := dimBrushOutline(tc.Points, tc.Width)
		if len(got) != len(tc.Ring) {
			t.Fatalf("%d points width %g: ring len %d != %d", len(tc.Points), tc.Width, len(got), len(tc.Ring))
		}
		for i, p := range got {
			if Distance(p, tc.Ring[i]) > 1e-8 {
				t.Fatalf("width %g ring %d: %v != %v", tc.Width, i, p, tc.Ring[i])
			}
		}
	}
}

func TestDim0CurveHitBoundsAndRoundTrip(t *testing.T) {
	s := NewScene()
	e := NewElement(KindArrow, 50, 60, 200, 80)
	e.DimArrow = true
	e.Roundness = &Roundness{Type: 2}
	e.Points = []Point{{0, 0}, {100, -60}, {200, 80}}
	e.EndArrowhead = "barb"
	s.Elements = append(s.Elements, e)
	points := DimArrowPoints(e)
	if len(points) != 33 || Distance(points[16], e.Points[1]) > 1e-8 {
		t.Fatal("curve does not pass through its editable midpoint")
	}
	for _, p := range points {
		world := Add(p, Point{e.X, e.Y})
		if !ElementBounds(e).Expand(1e-8).Contains(world) || !HitTest(e, world, 1) {
			t.Fatal("paint/hit/bounds disagree")
		}
	}
	raw, err := s.Encode()
	if err != nil {
		t.Fatal(err)
	}
	copy, err := Decode(raw)
	if err != nil {
		t.Fatal(err)
	}
	if !copy.Elements[0].DimArrow || copy.Elements[0].EndArrowhead != "barb" {
		t.Fatal("arrow style lost")
	}
	if len(ElementPrimitives(e)) < 2 {
		t.Fatal("missing arrow drawing")
	}
	e.StrokeWidth = 0
	if len(ElementPrimitives(e)) != 0 {
		t.Fatal("hidden arrow still draws")
	}
}

func TestDim0MultiPointCurveKeepsEveryVertex(t *testing.T) {
	e := NewElement(KindArrow, 0, 0, 300, 200)
	e.DimArrow = true
	e.Roundness = &Roundness{Type: 2}
	e.Points = []Point{{0, 0}, {50, 100}, {100, 0}, {200, 120}, {300, 0}, {350, 50}}
	points := DimArrowPoints(e)
	for _, vertex := range e.Points {
		found := false
		for _, p := range points {
			found = found || Distance(vertex, p) < 1e-8
		}
		if !found {
			t.Fatalf("curve discarded %v", vertex)
		}
	}
}

func TestDim0ShapeFlipMirrorsOutline(t *testing.T) {
	s := NewScene()
	e := NewDimShape("tag", 20, 30, 180, 110)
	s.Elements = append(s.Elements, e)
	before := ElementPrimitives(e)
	s.Flip([]string{e.ID}, true)
	after := ElementPrimitives(e)
	if e.Scale[0] != -1 {
		t.Fatal("shape flip not retained")
	}
	for i, p := range before {
		for j, op := range p.Ops {
			for k := 0; k+1 < len(op.Data); k += 2 {
				if math.Abs(after[i].Ops[j].Data[k]-(e.W-op.Data[k])) > 1e-8 {
					t.Fatal("outline was not mirrored")
				}
			}
		}
	}
}
